    "example": {
      "en": "23 × 100 = 2 300\n2.5 × 10 = 25\n4 500 ÷ 100 = 45\n3.7 × 0.1 = 0.37",
      "fr": "23 × 100 = 2 300\n2,5 × 10 = 25\n4 500 ÷ 100 = 45\n3,7 × 0,1 = 0,37"
    }
  },
